import numpy as np,hashlib,json,platform

def experiment(seed):
    rng=np.random.default_rng(seed);x=rng.normal(size=8);return {"mean":float(x.mean()),"sample":x.tolist()}
a=experiment(42);b=experiment(42);c=experiment(43)
print("same seed identical",a==b,"different seed identical",a==c)
data=np.arange(100,dtype=np.int64);fingerprint=hashlib.sha256(data.tobytes()).hexdigest()
manifest={"seed":42,"numpy":np.__version__,"python":platform.python_version(),"data_sha256":fingerprint}
print(json.dumps(manifest,indent=2))

## MATLAB — פונקציות רלוונטיות

| פונקציה / כלי | תפקיד |
|---|---|
| `rng` | seed ו-generator |
| `RandStream` | זרמים מקומיים/מקביליים |
| `DataHash או Java digest` | fingerprint |



```matlab
clear;rng(42,'twister');a=randn(8,1);rng(42,'twister');b=randn(8,1);
fprintf('same seed identical=%d\n',isequal(a,b));s=rng;disp(s);
data=int64(0:99);md=java.security.MessageDigest.getInstance('SHA-256');md.update(typecast(data,'uint8'));
hash=lower(join(string(dec2hex(typecast(md.digest(),'uint8'),2)),''));disp(hash);
```
